import os
import pytest
import envcfg


class TestPrecedence:
    def test_defaults_only(self):
        cfg = envcfg.load({"a": 1, "b": 2})
        assert cfg == {"a": 1, "b": 2}

    def test_toml_overrides_defaults(self, tmp_path):
        toml = tmp_path / "cfg.toml"
        toml.write_text("a = 10\n")
        cfg = envcfg.load({"a": 1, "b": 2}, toml_path=str(toml))
        assert cfg == {"a": 10, "b": 2}

    def test_env_overrides_toml(self, tmp_path):
        toml = tmp_path / "cfg.toml"
        toml.write_text("a = 10\n")
        cfg = envcfg.load({"a": 1, "b": 2}, toml_path=str(toml), env={"APP__A": "20"})
        assert cfg == {"a": 20, "b": 2}

    def test_nested_defaults(self):
        cfg = envcfg.load({"server": {"port": 80, "host": "localhost"}})
        assert cfg == {"server": {"port": 80, "host": "localhost"}}

    def test_nested_toml(self, tmp_path):
        toml = tmp_path / "cfg.toml"
        toml.write_text("[server]\nport = 9000\n")
        cfg = envcfg.load({"server": {"port": 80, "host": "localhost"}}, toml_path=str(toml))
        assert cfg == {"server": {"port": 9000, "host": "localhost"}}

    def test_nested_env(self, tmp_path):
        toml = tmp_path / "cfg.toml"
        toml.write_text("[server]\nport = 9000\n")
        cfg = envcfg.load({"server": {"port": 80, "host": "localhost"}}, toml_path=str(toml), env={"APP__SERVER__PORT": "8080"})
        assert cfg == {"server": {"port": 8080, "host": "localhost"}}


